// World Health & Disparities Practice Test 6. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–5.
import {q, mix} from './q.js';
const BARR='Barr, Health Disparities in the United States', WHO='WHO, Health Equity', NIMHD='National Institute on Minority Health and Health Disparities', KFF='KFF', OWID='Our World in Data';
const WH='What is Health', HD='Health Disparities & Diversity', TR='Disparities in Treatment & Medical Decisions', RED='Reducing Health Disparities';

export default {
 id:'world-health-disparities-6',
 event:'World Health & Disparities',
 title:'Practice Test 6',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Barr’s Health Disparities in the United States, WHO health equity materials, NIMHD, KFF and Our World in Data',
 plan:[{area:WH,weight:20},{area:HD,weight:40},{area:TR,weight:20},{area:RED,weight:20}],
 questions:mix([
  q(WH,'The number of deaths per 1,000 people in a population each year, without adjusting for age, is called the:','Crude death rate',['Age-adjusted rate','Case fatality rate','Infant mortality rate'],'A','Crude rates are easy to calculate but can mislead when populations have different age structures.',OWID),
  q(WH,'Why do researchers use age-adjusted death rates to compare two countries?','To remove the effect of differences in age structure',['To count only deaths among children','To include deaths from all past decades','To make every country’s rate the same'],'B','A country with many older people will have more deaths even if its health care is excellent.',OWID),
  q(WH,'A DALY combines years of life lost to early death with which other measure?','Years lived with disability',['Years spent in school','Years of paid employment','Years spent in a hospital'],'C','DALYs = years of life lost + years lived with disability; one DALY equals one lost year of healthy life.',WHO),
  q(WH,'Screening for high blood pressure to find disease early, before symptoms, is which level of prevention?','Secondary prevention',['Primary prevention','Tertiary prevention','Primordial prevention'],'D','Primary prevents disease, secondary detects it early and tertiary limits its effects.',WHO),
  q(WH,'Which view holds that disability results mainly from barriers in society, such as inaccessible buildings, rather than from a person’s body?','The social model of disability',['The medical model of disability','The charity model of disability','The moral model of disability'],'A','Removing barriers, such as adding ramps and captions, is the focus of this model.',WHO),
  q(WH,'Marketing of tobacco, alcohol, sugary drinks and ultra-processed foods is part of which group of influences on health?','Commercial determinants of health',['Genetic determinants of health','Biological determinants of health','Clinical determinants of health'],'B','Business practices and products can shape health as strongly as personal choices.',WHO),
  q(WH,'Which legally binding international agreement, revised in 2005, requires countries to report certain disease events to the WHO?','International Health Regulations',['Geneva Conventions','Paris Climate Agreement','Universal Declaration of Human Rights'],'C','The regulations aim to stop the international spread of disease while avoiding needless travel and trade limits.',WHO),
  q(WH,'How does the World Bank sort countries into low, lower-middle, upper-middle and high income groups?','By gross national income per person',['By total population size','By life expectancy at birth','By land area'],'D','Income groups help compare health outcomes among countries at similar levels of wealth.',OWID),
  q(WH,'Which field studies how the health of human civilization depends on the health of Earth’s natural systems?','Planetary health',['Occupational health','Veterinary health','Clinical health'],'A','Planetary health links issues such as climate change, biodiversity loss and pollution to human health.',WHO),
  q(WH,'Which 1966 UN treaty recognizes everyone’s right to “the highest attainable standard” of physical and mental health?','International Covenant on Economic, Social and Cultural Rights',['International Covenant on Civil and Political Rights','Convention on the Law of the Sea','Treaty on the Non-Proliferation of Nuclear Weapons'],'B','Article 12 of this covenant is often cited as the basis of the right to health.',WHO),
  q(HD,'Which autoimmune disease is two to three times more common in Black women than in white women?','Lupus',['Multiple sclerosis','Celiac disease','Type 1 diabetes'],'C','Black women with lupus also tend to develop it younger and have more severe kidney involvement.',NIMHD),
  q(HD,'Which U.S. group has the highest rate of preterm birth?','Black infants',['Asian American infants','White infants','Hispanic infants'],'D','Preterm birth is a leading cause of the higher infant death rate among Black infants.',NIMHD),
  q(HD,'Compared with white older adults, Black older adults in the U.S. are about how likely to have Alzheimer’s disease or another dementia?','About twice as likely',['About half as likely','Equally likely','About ten times as likely'],'A','Higher rates of hypertension and diabetes may contribute to this gap.',NIMHD),
  q(HD,'Which group in the U.S. has the highest rate of firearm homicide death?','Young Black men',['Older white men','Young Asian American women','Middle-aged Hispanic women'],'B','Community violence intervention programs aim to reduce this large disparity.',NIMHD),
  q(HD,'Why are death rates from motor vehicle crashes higher in rural areas?','Higher speeds and longer waits for trauma care',['Rural roads have far more traffic lights and stop signs','Rural drivers are much younger than city drivers on average','Rural areas rely more on crowded public transit buses'],'C','Distance from trauma care means injured people may wait longer for treatment.',BARR),
  q(HD,'Which group of U.S. children has the highest rate of obesity?','Hispanic children',['Asian American children','White children','Children of college graduates'],'D','Food access, marketing, income and neighborhood safety all contribute.',NIMHD),
  q(HD,'In recent CDC data, which group had the highest drug overdose death rate in the U.S.?','American Indian and Alaska Native people',['Asian American people','Non-Hispanic white people over 65','Hispanic adolescents'],'A','Overdose rates also rose sharply among Black Americans in the same period.',NIMHD),
  q(HD,'Children from low-income families are more likely than other children to have which oral health problem?','Untreated tooth decay',['Too many dental visits','Excess fluoride intake','Crooked teeth only'],'B','Lack of dental insurance and few nearby dentists limit preventive care.',NIMHD),
  q(HD,'Which eye disease is the leading cause of blindness among Black Americans?','Glaucoma',['Cataracts','Pink eye','Nearsightedness'],'C','Glaucoma tends to start earlier and progress faster in Black patients, so early screening matters.',NIMHD),
  q(HD,'Which group of U.S. women experiences the highest rates of intimate partner violence?','American Indian and Alaska Native women',['Asian American women','White women over 65','Women with graduate degrees'],'D','Jurisdiction issues on tribal lands have made it harder to prosecute some offenders.',NIMHD),
  q(HD,'Why is medical debt considered both a result and a cause of health disparities?','It leads people to delay care, which can worsen health',['It improves credit scores over time','It only affects people with insurance','It has no effect on whether people seek care'],'A','People with medical debt are more likely to skip care and medicines because of cost.',KFF),
  q(HD,'Neighborhoods where residents must travel far to fill a prescription are called:','Pharmacy deserts',['Medical homes','Health enterprise zones','Pharmacy clusters'],'B','Pharmacy closures often hit low-income and minority neighborhoods hardest.',BARR),
  q(HD,'Rising rents push long-time, lower-income residents out of a neighborhood as wealthier people move in. What is this process?','Gentrification',['Redlining','Annexation','Suburbanization'],'C','Displacement can break social ties and disrupt access to familiar clinics and services.',BARR),
  q(HD,'The trust, networks and shared norms within a community that help people cooperate are called:','Social capital',['Human capital','Financial capital','Physical capital'],'D','Communities with strong social capital often have better health outcomes.',BARR),
  q(HD,'Camara Jones describes three levels of racism. Which list names them?','Institutional, personally mediated and internalized',['Federal, state, county and local government levels','Mild, moderate, severe and life-threatening','Historical, generational, current and future'],'A','Her “Gardener’s Tale” uses a garden to show how each level affects health.',BARR),
  q(HD,'Which issue does the WHO describe as a major global public health problem that most affects women?','Gender-based violence',['Excess vitamin intake','Too much physical activity','Overuse of dental care'],'B','About one in three women worldwide experience physical or sexual violence in their lifetime.',WHO),
  q(HD,'Why do refugees often have unmet health needs when they arrive in a new country?','Their care was interrupted by conflict and displacement',['They are always in better health than residents','They arrive with full medical records','They have no chronic illnesses'],'C','Screening and linking refugees to care early can prevent complications.',WHO),
  q(HD,'Why do people living near major highways face higher rates of asthma and heart disease?','Higher exposure to fine particle pollution',['Lower noise levels at night','More green space nearby','Cleaner indoor air'],'D','Fine particles (PM2.5) reach deep into the lungs and bloodstream.',WHO),
  q(HD,'As smoking falls in wealthy countries, where is tobacco use now concentrated?','Low- and middle-income countries',['Only high-income countries','Only among older adults in Europe','Nowhere; it has nearly ended worldwide'],'A','About 80% of the world’s tobacco users live in low- and middle-income countries.',WHO),
  q(HD,'According to the WHO, what is the leading cause of death for children and young people aged 5 to 29?','Road traffic injuries',['Heart disease and stroke','Childhood cancers','Type 1 diabetes'],'B','Most road deaths occur in low- and middle-income countries, though they have fewer vehicles.',WHO),
  q(TR,'For the same severity of knee arthritis, which joint surgery do Black patients receive less often than white patients?','Total knee replacement',['Pain medicine of any kind','Physical therapy referral','An X-ray of the knee'],'C','Differences in referral, trust and information all contribute to this gap.',BARR),
  q(TR,'How can strict clinical trial eligibility rules contribute to disparities?','They may exclude people with other conditions or limited English',['They always guarantee diverse study groups','They make results apply to everyone equally','They require trials to include all age groups'],'D','Results may then not apply well to the patients who most need the treatment.',NIMHD),
  q(TR,'Which CDC campaign encourages people to listen to and act on the concerns of pregnant and postpartum women?','Hear Her',['Tips From Former Smokers','Know Your Numbers','Choose My Plate'],'A','Many pregnancy-related deaths follow warning signs that were dismissed.',NIMHD),
  q(TR,'Words such as “noncompliant” or “claims” in medical notes, used more often for some groups, are examples of:','Stigmatizing language',['Plain language','Person-first language','Technical language'],'B','Biased wording in records can influence how later clinicians view and treat the patient.',BARR),
  q(TR,'Which program encourages patients to ask three questions: What is my main problem? What do I need to do? Why is it important?','Ask Me 3',['Teach-back','SBAR','Choosing Wisely'],'C','The questions help patients with any level of health literacy understand their care.',BARR),
  q(TR,'Brief, everyday comments or actions that send negative messages to members of a group, often unintentionally, are called:','Microaggressions',['Microloans','Microbiomes','Micronutrients'],'D','Repeated microaggressions in care settings can erode trust and make patients less likely to return.',BARR),
  q(TR,'Studies have found that Black patients with mood symptoms are more often diagnosed with which condition instead?','Schizophrenia',['Depression','Bipolar disorder','Anxiety'],'A','Misdiagnosis can lead to the wrong medicines and missed treatment for mood disorders.',BARR),
  q(TR,'Which 1947 code, written after Nazi medical experiments, made voluntary consent essential in human research?','Nuremberg Code',['Hippocratic Oath','Belmont Report','Declaration of Helsinki'],'B','Its first principle is that the voluntary consent of the human subject is absolutely essential.',BARR),
  q(TR,'Training that teaches clinicians to see how policies and systems shape patients’ health, beyond culture, is called:','Structural competency',['Cultural tourism','Clinical neutrality','Technical competency'],'C','Structural competency looks at causes such as housing, zoning and insurance rules.',BARR),
  q(TR,'Which standardized surveys ask patients about their experiences with care, such as how well clinicians communicated?','CAHPS surveys',['Census surveys','Gallup polls','Nielsen ratings'],'D','Comparing CAHPS results by group can reveal differences in how patients are treated.',KFF),
  q(RED,'Which approach provides services for everyone but scales their intensity to the level of need?','Proportionate universalism',['Strict targeting','Equal rationing','Means testing only'],'A','It avoids the stigma of targeted programs while still reaching those most in need.',WHO),
  q(RED,'Clinicians refer patients to nonmedical community activities, such as walking groups or art classes, to improve health. What is this?','Social prescribing',['E-prescribing','Off-label prescribing','Step therapy'],'B','Social prescribing addresses loneliness and other social needs.',WHO),
  q(RED,'Under the Affordable Care Act, nonprofit hospitals must complete which assessment every three years?','A community health needs assessment',['A malpractice insurance audit','A building safety inspection','A staff satisfaction survey'],'C','Hospitals must also adopt a plan to address the needs they identify.',KFF),
  q(RED,'Which program makes it safer for children to walk and bike to school, through sidewalks, crossings and education?','Safe Routes to School',['No Child Left Behind','Head Start','Title IX'],'D','Changes to the built environment can increase activity in neighborhoods with fewer safe spaces.',BARR),
  q(RED,'Which international financing organization funds programs against three major infectious diseases in low- and middle-income countries?','The Global Fund',['The World Trade Organization','The Bretton Woods Fund','The Marshall Plan'],'A','The Global Fund supports AIDS, TB and malaria programs and claims to have saved tens of millions of lives.',WHO),
  q(RED,'Training community health workers to perform some tasks usually done by doctors or nurses is called:','Task shifting',['Brain drain','Upcoding','Cost shifting'],'B','Task shifting helps countries with few clinicians reach more people.',WHO),
  q(RED,'Which WHO and UNICEF program recognizes hospitals that support breastfeeding through steps such as rooming-in?','Baby-Friendly Hospital Initiative',['Magnet Recognition Program','Joint Commission accreditation','Leapfrog Hospital Survey'],'C','Baby-Friendly practices have helped raise breastfeeding rates in many communities.',WHO),
  q(RED,'Which federal program has offered early education, health and nutrition services to low-income preschool children since 1965?','Head Start',['WIC','Title X','SNAP-Ed'],'D','Head Start includes health screenings and links families to medical and dental care.',KFF),
  q(RED,'Which historically Black medical schools have trained a large share of Black physicians in the United States?','Howard, Meharry and Morehouse',['Harvard, Yale and Stanford','Duke, Emory and Vanderbilt','Johns Hopkins, Penn and Columbia'],'A','Graduates of these schools are more likely to practice in underserved communities.',NIMHD),
  q(RED,'Collecting accurate race, ethnicity and language data on every patient helps hospitals do what?','Find and track gaps in care by group',['Charge some patients more','Decide which patients to turn away','Replace interpreter services'],'B','Without good demographic data, disparities inside a hospital can stay hidden.',NIMHD)
 ],9641)
};
